<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class ApplicantPortalController extends Controller{
 public function register(){return view('applicant.register');}
 public function create(Request $r){$d=$r->validate(['last_name'=>'required|string|max:100','first_name'=>'required|string|max:100','middle_name'=>'nullable|string|max:100','birth_date'=>'required|date','phone'=>'required|string|max:100','email'=>'required|email|max:255','personal_data_consent'=>'accepted']);unset($d['personal_data_consent']);$token=Str::random(64);$id=DB::table('admission_applicants')->insertGetId($d+['portal_token'=>$token,'portal_status'=>'draft','personal_data_consent_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('applicant.portal',['token'=>$token]);}
 public function show(Request $r,$token){$a=$this->applicant($token);$campaigns=DB::table('admission_campaigns')->where('status','active')->whereDate('starts_on','<=',today())->whereDate('ends_on','>=',today())->get();$targets=DB::table('admission_targets as t')->join('admission_campaigns as c','c.id','=','t.campaign_id')->join('specialties as sp','sp.id','=','t.specialty_id')->whereIn('t.campaign_id',$campaigns->pluck('id'))->select('t.*','c.name as campaign_name','sp.code','sp.name as specialty')->get();$applications=DB::table('admission_applications as ap')->join('admission_targets as t','t.id','=','ap.target_id')->join('specialties as sp','sp.id','=','t.specialty_id')->where('ap.applicant_id',$a->id)->select('ap.*','sp.code','sp.name as specialty')->orderBy('ap.priority')->get();$documents=DB::table('admission_documents')->where('applicant_id',$a->id)->orderBy('document_type')->get();$campaignIds=$applications->pluck('campaign_id')->unique();$requirements=DB::table('admission_document_requirements')->whereIn('campaign_id',$campaignIds)->where('active',1)->orderBy('sort_order')->get();$messages=DB::table('admission_messages')->where('applicant_id',$a->id)->orderByDesc('id')->get();return view('applicant.portal',compact('a','targets','applications','documents','requirements','messages'));}
 public function profile(Request $r,$token){$a=$this->applicant($token);abort_if($a->portal_status==='verified',423,'Анкета уже проверена приёмной комиссией.');$d=$r->validate(['last_name'=>'required|string|max:100','first_name'=>'required|string|max:100','middle_name'=>'nullable|string|max:100','birth_date'=>'required|date','phone'=>'required|string|max:100','email'=>'required|email|max:255','document_number'=>'nullable|string|max:100']);DB::table('admission_applicants')->where('id',$a->id)->update($d+['updated_at'=>now()]);return back()->with('success','Анкета сохранена.');}
 public function application(Request $r,$token){$a=$this->applicant($token);$d=$r->validate(['target_id'=>'required|exists:admission_targets,id','priority'=>'required|integer|min:1|max:99']);$t=DB::table('admission_targets')->find($d['target_id']);abort_if(!$t||!DB::table('admission_campaigns')->where('id',$t->campaign_id)->where('status','active')->exists(),422,'Приём по выбранной программе закрыт.');DB::table('admission_applications')->insert($d+['applicant_id'=>$a->id,'campaign_id'=>$t->campaign_id,'original_document'=>0,'status'=>'submitted','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Заявление подано.');}
 public function document(Request $r,$token){$a=$this->applicant($token);$d=$r->validate(['requirement_id'=>'required|exists:admission_document_requirements,id','file'=>'required|file|mimes:pdf,jpg,jpeg,png|max:10240','series'=>'nullable|string|max:50','number'=>'nullable|string|max:100','issued_on'=>'nullable|date','issued_by'=>'nullable|string|max:500']);$req=DB::table('admission_document_requirements')->find($d['requirement_id']);abort_unless(DB::table('admission_applications')->where(['applicant_id'=>$a->id,'campaign_id'=>$req->campaign_id])->exists(),403);$old=DB::table('admission_documents')->where(['applicant_id'=>$a->id,'requirement_id'=>$req->id])->first();$path=$r->file('file')->store('admission/'.$a->id,'local');DB::table('admission_documents')->updateOrInsert(['applicant_id'=>$a->id,'requirement_id'=>$req->id],['document_type'=>$req->name,'series'=>$d['series']??null,'number'=>$d['number']??null,'issued_on'=>$d['issued_on']??null,'issued_by'=>$d['issued_by']??null,'file_path'=>$path,'status'=>'submitted','moderation_note'=>null,'moderated_by'=>null,'moderated_at'=>null,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Документ загружен и отправлен на проверку.');}
 public function submit(Request $r,$token){$a=$this->applicant($token);abort_unless($a->personal_data_consent_at,422,'Требуется согласие на обработку персональных данных.');abort_unless(DB::table('admission_applications')->where('applicant_id',$a->id)->exists(),422,'Сначала подайте хотя бы одно заявление.');DB::table('admission_applicants')->where('id',$a->id)->update(['portal_status'=>'submitted','submitted_at'=>now(),'updated_at'=>now()]);return back()->with('success','Анкета отправлена в приёмную комиссию.');}
 private function applicant($token){$a=DB::table('admission_applicants')->where('portal_token',$token)->first();abort_if(!$a,404);return $a;}
}